(10, 'breakfast', 'breakfast', 'Thattu Dosa (Set – 3 Nos)', 'Traditional small spongy dosas served with stone-ground chutney and sambar', '75.00', 'Set of 3', 'Tender, spongy thattu dosas roasted on hot tawa with farm ghee or oil, served with fresh coconut chutney and piping hot sambar.', '3 Spongy Thattu Dosas\nFresh Coconut Chutney\nEarthen Pot Sambar', 'veg', 'ESTATE TIFFIN', 'assets/images/food_dosa_set.jpg', '[\"assets\\/images\\/food_dosa_set.jpg\"]', 1, 1, '2026-10-04 12:50:32'),
(11, 'breakfast', 'breakfast', 'Masala Dosa', 'Crisp golden crepe filled with gently spiced tempered potato masala', '100.00', 'Per Plate', 'Crispy golden roasted dosa lined with aromatic spices, wrapped around savory potato masala with mustard and curry leaves.', '1 Crisp Masala Dosa\nPotato Masala Filling\nCoconut & Tomato Chutneys\nHot Vegetable Sambar', 'veg', 'POPULAR', 'assets/images/food_dosa_set.jpg', '[\"assets\\/images\\/food_dosa_set.jpg\"]', 2, 1, '2026-10-04 12:50:32'),
(12, 'breakfast', 'breakfast', 'Egg Dosa', 'Crisp dosa topped with farm-fresh beaten egg, crushed pepper and shallots', '75.00', 'Per Plate', 'Hot roasted dosa enriched with a freshly beaten country egg, spiced with freshly ground mountain black pepper and green chilies.', '1 Egg Enriched Dosa\nCoconut Chutney\nPiping Sambar', 'non-veg', 'FARM EGG', 'assets/images/food_dosa_set.jpg', '[\"assets\\/images\\/food_dosa_set.jpg\"]', 3, 1, '2026-10-04 12:50:32'),
(13, 'breakfast', 'breakfast', 'Idli (Set – 3 Nos)', 'Pillowy steamed fermented rice and black lentil cakes', '75.00', 'Set of 3', 'Soft, melt-in-the-mouth steamed idlis made from naturally fermented native grain batter, paired with stone-ground coconut chutney.', '3 Steamed Soft Idlis\nCoconut Chutney\nVegetable Sambar', 'veg', 'LIGHT & HEALTHY', 'assets/images/01 (10).jpeg', '[\"assets\\/images\\/01 (10).jpeg\"]', 4, 1, '2026-10-04 12:50:32'),
(14, 'breakfast', 'breakfast', 'Idiyappam', 'Delicate steamed string hoppers made of roasted rice flour', '20.00', 'Per Piece', 'Silky soft steamed rice vermicelli nests, wonderful with vegetable stew or spicy kadala curry.', 'Steamed Rice Idiyappam\nFreshly Prepared', 'veg', 'CLASSIC', 'assets/images/food_appam_stew.jpg', '[\"assets\\/images\\/01 (10).jpeg\"]', 5, 1, '2026-10-04 12:50:32'),
(15, 'breakfast', 'breakfast', 'Puttu', 'Steamed cylinders of coarsely ground rice layered with fresh coconut', '30.00', 'Per Piece', 'Traditional aromatic steamed puttu layered with freshly grated sweet coconut from the sanctuary estate.', 'Steamed Bamboo Puttu\nFresh Grated Coconut', 'veg', 'KERALA SPECIAL', 'assets/images/food_puttu_kadala.jpg', '[\"assets\\/images\\/01 (1).jpeg\"]', 6, 1, '2026-10-04 12:50:32'),
