-- -------------------------------------------------------------
-- Table structure for `gallery`
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `gallery`;
CREATE TABLE `gallery` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(200) NOT NULL,
  `caption` text DEFAULT NULL,
  `tag` varchar(100) DEFAULT NULL,
  `category` varchar(100) DEFAULT 'Landscape',
  `category_slug` varchar(100) DEFAULT NULL,
  `image_url` varchar(255) NOT NULL,
  `photos` text DEFAULT NULL,
  `display_order` int(11) DEFAULT 0,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Dumping data for table `gallery` (9 records)
INSERT INTO `gallery` (`id`, `title`, `caption`, `tag`, `category`, `category_slug`, `image_url`, `photos`, `display_order`, `is_active`, `created_at`) VALUES
(1, 'High Canopy Treehouse in Mist', 'Perched 30 feet above the forest floor among silver oaks, overlooking rolling valley clouds.', 'CANOPY DWELLING ?? 1,640M', 'Villas & Stays', 'dwellings', 'assets/images/treehouse_exterior.png', '[{\"src\":\"assets\\/images\\/treehouse_exterior.png\",\"title\":\"Canopy Treehouse in Morning Mist\",\"caption\":\"Rising 30 feet into the Kanthalloor sky with panoramic views of the eastern valley.\"},{\"src\":\"assets\\/images\\/treehouse_exterior_front.jpg\",\"title\":\"Cantilevered Teak Balcony\",\"caption\":\"Private forest deck facing morning sunrise and drifting cloud waves.\"},{\"src\":\"assets\\/images\\/treehouse_interior.png\",\"title\":\"Loft Artisan Bedroom Suite\",\"caption\":\"Warm reclaimed timber, panoramic glass walls, and handcrafted linens.\"},{\"src\":\"assets\\/images\\/treehouse_360_pano.jpg\",\"title\":\"360\\u00b0 Shola Forest Panorama\",\"caption\":\"Surrounded by dense forest foliage, birdsong, and crisp mountain breeze.\"},{\"src\":\"assets\\/images\\/01 (10).jpeg\",\"title\":\"Twilight Balcony Glow\",\"caption\":\"Soft evening lighting filtering through the tree canopy as darkness falls.\"},{\"src\":\"assets\\/images\\/01 (25).jpeg\",\"title\":\"Morning Fog Horizon\",\"caption\":\"Awakening above the cloud blanket across the Western Ghats range.\"}]', 1, 1, '2026-09-14 01:08:16'),
(2, 'Hand-Sculpted Cob Mudhouse', 'Naturally insulated clay and sand architecture with private herbal garden courtyards.', 'EARTHEN ARCHITECTURE', 'Handcrafted Living', 'dwellings', 'assets/images/mudhouse_exterior.png', '[{\"src\":\"assets\\/images\\/mudhouse_exterior.png\",\"title\":\"Cob Mudhouse Cottage Frontage\",\"caption\":\"Naturally breathable earthen walls that maintain cool temperatures by day and warmth by night.\"},{\"src\":\"assets\\/images\\/mudhouse_interior.png\",\"title\":\"Earthen Living Room & Hearth\",\"caption\":\"Organic textures, slate stone floors, and hand-carved wooden fixtures.\"},{\"src\":\"assets\\/images\\/01 (7).jpeg\",\"title\":\"Terracotta Veranda & Cob Wall\",\"caption\":\"Traditional clay roof tiles with sweeping views of the organic vegetable terraces.\"},{\"src\":\"assets\\/images\\/01 (20).jpeg\",\"title\":\"Mudhouse by Campfire Hearth\",\"caption\":\"Gentle crackle of open fires warming the terracotta courtyard at twilight.\"},{\"src\":\"assets\\/images\\/01 (17).jpeg\",\"title\":\"Herbal Garden Courtyard Walk\",\"caption\":\"Fragrant rosemary, lavender, and lemongrass bordering the mudhouse paths.\"},{\"src\":\"assets\\/images\\/01 (2).jpeg\",\"title\":\"Artisan Handcrafted Bedroom\",\"caption\":\"Peaceful sanctuary designed for deep rest away from digital screens.\"}]', 2, 1, '2026-09-14 01:08:16'),
(3, 'The Western Ghats Vista', 'High-altitude horizon cloaked in shifting clouds and untouched shola wilderness.', 'ALPINE HORIZON', 'Landscape', 'landscape', 'assets/images/01 (25).jpeg', '[{\"src\":\"assets\\/images\\/01 (25).jpeg\",\"title\":\"High-Altitude Valley Horizon\",\"caption\":\"Sweeping vistas of the Anaimudi foothills and dense mountain slopes.\"},{\"src\":\"assets\\/images\\/01 (26).jpeg\",\"title\":\"Misty Ridges & Cloud Waves\",\"caption\":\"Clouds sweeping through the valley canyons during early morning hours.\"},{\"src\":\"assets\\/images\\/01 (27).jpeg\",\"title\":\"Perennial Brook Stream\",\"caption\":\"Pure mineral water cascading through mossy boulders across the sanctuary.\"},{\"src\":\"assets\\/images\\/01 (28).jpeg\",\"title\":\"Golden Hour Mountain Silhouette\",\"caption\":\"Sunlight breaking across the eastern mountain ridge.\"},{\"src\":\"assets\\/images\\/01 (29).jpeg\",\"title\":\"Ancient Shola Forest Grove\",\"caption\":\"Centuries-old biodiversity hotspot home to rare flora and fauna.\"},{\"src\":\"assets\\/images\\/01 (30).jpeg\",\"title\":\"Twilight Valley Panorama\",\"caption\":\"Serene purple twilight settling over the high-range tea gardens.\"}]', 3, 1, '2026-09-14 01:08:16'),
(4, 'Woodfire Claypot Lunch', 'Pure farm-to-table cooking over slow embers using hand-ground spices and organic produce.', 'EARTHEN GASTRONOMY', 'Gastronomy', 'gastronomy', 'assets/images/01 (3).jpeg', '[{\"src\":\"assets\\/images\\/01 (3).jpeg\",\"title\":\"Claypot Simmering on Open Fire\",\"caption\":\"Slow-cooked heirloom grains and vegetables infused with natural wood smoke.\"},{\"src\":\"assets\\/images\\/food_kerala_sadya.jpg\",\"title\":\"Traditional Farm Feast (Sadya)\",\"caption\":\"Served on fresh banana leaves with organic estate-grown vegetables and spices.\"},{\"src\":\"assets\\/images\\/food_dosa_set.jpg\",\"title\":\"Crisp Morning Dosa & Chutneys\",\"caption\":\"Stone-ground fermented batter with fresh mountain coconut and mint chutneys.\"},{\"src\":\"assets\\/images\\/food_evening_snacks.jpg\",\"title\":\"Twilight Spiced Tea & Snacks\",\"caption\":\"Steaming cardamom mountain tea paired with hot steamed herbal snacks.\"},{\"src\":\"assets\\/images\\/01 (4).jpeg\",\"title\":\"Open-Air Forest Dining Deck\",\"caption\":\"Savoring wholesome organic meals surrounded by the rustle of leaves.\"},{\"src\":\"assets\\/images\\/01 (5).jpeg\",\"title\":\"The Earthen Kitchen Hearth\",\"caption\":\"Where age-old culinary secrets and slow nourishment come to life.\"}]', 4, 1, '2026-09-14 01:08:16'),
(5, 'Organic Winter Apple Orchards', 'Ancient heirloom trees yielding sweet, pesticide-free mountain apples each winter.', 'ESTATE HARVEST', 'Orchards', 'orchards', 'assets/images/01 (1).jpeg', '[{\"src\":\"assets\\/images\\/01 (1).jpeg\",\"title\":\"Terraced Apple Orchard Rows\",\"caption\":\"Heirloom apple trees flourishing in the sub-tropical temperate microclimate of Kanthalloor.\"},{\"src\":\"assets\\/images\\/01 (11).jpeg\",\"title\":\"Fresh Hand-Plucked Apples\",\"caption\":\"Crisp, sweet, and bursting with natural flavor straight from the tree.\"},{\"src\":\"assets\\/images\\/01 (12).jpeg\",\"title\":\"Lush Passion Fruit Trellises\",\"caption\":\"Organic passion fruit vines draping over natural bamboo pergolas.\"},{\"src\":\"assets\\/images\\/01 (13).jpeg\",\"title\":\"Wild Berry & Plum Trees\",\"caption\":\"Sweet seasonal berries harvested for fresh jams and morning preserves.\"},{\"src\":\"assets\\/images\\/01 (14).jpeg\",\"title\":\"Orchard Walking Pathway\",\"caption\":\"Stone-lined walking paths winding through the organic fruit groves.\"}]', 5, 1, '2026-09-14 01:08:16'),
(6, 'Stargazing by the Cob Hearth', 'Night skies at 1,600m altitude illuminated only by campfire crackle and constellations.', 'NIGHT SKY SANCTUARY', 'Nightscape', 'landscape', 'assets/images/01 (20).jpeg', '[{\"src\":\"assets\\/images\\/01 (20).jpeg\",\"title\":\"Cob Hearth Campfire Circle\",\"caption\":\"Gathering around the warm coals under an unpolluted Milky Way galaxy.\"},{\"src\":\"assets\\/images\\/01 (21).jpeg\",\"title\":\"Starlit Mountain Canopy\",\"caption\":\"Zero light pollution allows clear visibility of shooting stars and constellations.\"},{\"src\":\"assets\\/images\\/01 (22).jpeg\",\"title\":\"Lantern-Lit Stone Paths\",\"caption\":\"Subtle warm ambient lighting guiding your way through the night forest.\"},{\"src\":\"assets\\/images\\/01 (23).jpeg\",\"title\":\"Evening Fire Ritual\",\"caption\":\"Sharing stories, folklore, and quiet acoustic music by the hearth.\"},{\"src\":\"assets\\/images\\/01 (24).jpeg\",\"title\":\"Moonlight Over the Valleys\",\"caption\":\"Silvery moonlight casting a tranquil glow over the mountain contours.\"}]', 6, 1, '2026-09-14 01:08:16'),
(7, 'Morning Dew on Passion Fruit Vines', 'Wild pollinators and lush flora flourishing in our certified chemical-free sanctuary.', 'BOTANICAL HARMONY', 'Flora', 'orchards', 'assets/images/01 (15).jpeg', '[{\"src\":\"assets\\/images\\/01 (15).jpeg\",\"title\":\"Morning Dew on Passion Fruit Vines\",\"caption\":\"Crystal dewdrops clinging to wild tendrils in the early dawn light.\"},{\"src\":\"assets\\/images\\/01 (16).jpeg\",\"title\":\"Wild Shola Orchids & Ferns\",\"caption\":\"Endemic ferns and rare orchids thriving in the moist mountain air.\"},{\"src\":\"assets\\/images\\/01 (18).jpeg\",\"title\":\"Medicinal Herb Sanctuary\",\"caption\":\"Cultivating tulsi, lemongrass, brahmi, and wild forest herbs.\"},{\"src\":\"assets\\/images\\/01 (19).jpeg\",\"title\":\"Canopy Epiphytes & Silver Oaks\",\"caption\":\"Lush mosses and air plants thriving on towering mountain trees.\"},{\"src\":\"assets\\/images\\/01 (31).jpeg\",\"title\":\"Brook-Side Wildflowers\",\"caption\":\"Vibrant blossoms lining the banks of the perennial forest brook.\"}]', 7, 1, '2026-09-14 01:08:16'),
(8, 'Living Mud Courtyard Veranda', 'Unpaved, breathable courtyards connecting guest quarters directly with the soil.', 'BIOPHILIC SPACES', 'Architecture', 'dwellings', 'assets/images/01 (7).jpeg', '[{\"src\":\"assets\\/images\\/01 (7).jpeg\",\"title\":\"Living Mud Courtyard Veranda\",\"caption\":\"Terracotta verandas designed for slow morning teas and peaceful contemplation.\"},{\"src\":\"assets\\/images\\/01 (8).jpeg\",\"title\":\"Natural Light & Breathable Clay\",\"caption\":\"Deep overhangs that keep out harsh sun while welcoming cool valley breezes.\"},{\"src\":\"assets\\/images\\/01 (9).jpeg\",\"title\":\"Earthen Seating Nook\",\"caption\":\"Cob benches sculpted directly out of native red clay and river sand.\"},{\"src\":\"assets\\/images\\/01 (32).jpeg\",\"title\":\"Hand-Cut Stone Pathways\",\"caption\":\"Meandering flagstone walkways harmoniously embedded in clover and grass.\"},{\"src\":\"assets\\/images\\/01 (33).jpeg\",\"title\":\"Sunrise on the Veranda\",\"caption\":\"Watch the morning mist dissipate from the comfort of a shaded patio.\"}]', 8, 1, '2026-09-14 01:08:16'),
(9, 'ehse', 'atr', 'SANCTUARY ARCHIVE', 'Landscape', NULL, 'assets/images/01 (1).jpeg', '[{\"src\":\"assets\\/images\\/01 (1).jpeg\",\"title\":\"ehse\",\"caption\":\"atr\"}]', 9, 1, '2026-09-15 00:33:42');

-- -------------------------------------------------------------
-- Table structure for `inquiries`
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `inquiries`;
CREATE TABLE `inquiries` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(150) NOT NULL,
  `email` varchar(150) NOT NULL,
  `phone` varchar(50) DEFAULT NULL,
  `subject` varchar(200) DEFAULT NULL,
  `message` text NOT NULL,
  `status` varchar(50) DEFAULT 'unread',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------
-- Table structure for `room_ical_feeds`
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `room_ical_feeds`;
CREATE TABLE `room_ical_feeds` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `room_slug` varchar(100) NOT NULL,
  `channel_name` varchar(100) NOT NULL,
  `feed_url` text NOT NULL,
  `last_synced_at` datetime DEFAULT NULL,
  `sync_status` varchar(50) DEFAULT 'pending',
  `sync_error` text DEFAULT NULL,
  `sync_events_count` int(11) DEFAULT 0,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------
-- Table structure for `rooms`
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `rooms`;
CREATE TABLE `rooms` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `slug` varchar(100) NOT NULL,
  `stay_type` varchar(50) DEFAULT 'treehouse',
  `structure_type` varchar(50) DEFAULT 'single_hut',
  `title` varchar(150) NOT NULL,
  `rate_per_night` decimal(10,2) NOT NULL,
  `single_room_rate` decimal(10,2) DEFAULT NULL,
  `extra_guest_rate` decimal(10,2) DEFAULT 1500.00,
  `extra_child_rate` decimal(10,2) DEFAULT 800.00,
  `elevation` varchar(100) DEFAULT NULL,
  `min_guests` int(11) DEFAULT 2,
  `base_guests` int(11) DEFAULT 2,
  `max_guests` int(11) DEFAULT 2,
  `description` text DEFAULT NULL,
  `amenities` text DEFAULT NULL,
  `inventory_checklist` text DEFAULT NULL,
  `image_url` varchar(255) DEFAULT NULL,
  `photos` longtext DEFAULT NULL,
  `photos_left` text DEFAULT NULL,
  `photos_right` text DEFAULT NULL,
  `interior_360_url` varchar(255) DEFAULT NULL,
  `tour_stages_json` longtext DEFAULT NULL,
  `is_available` tinyint(1) DEFAULT 1,
  `availability_status` varchar(50) DEFAULT 'available',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`)
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Dumping data for table `rooms` (10 records)
INSERT INTO `rooms` (`id`, `slug`, `stay_type`, `structure_type`, `title`, `rate_per_night`, `single_room_rate`, `extra_guest_rate`, `extra_child_rate`, `elevation`, `min_guests`, `base_guests`, `max_guests`, `description`, `amenities`, `inventory_checklist`, `image_url`, `photos`, `photos_left`, `photos_right`, `interior_360_url`, `tour_stages_json`, `is_available`, `availability_status`, `created_at`) VALUES
(15, 'mudhouse-stay', 'woodhouse', 'single_hut', 'Earthen Mudhouse Suite', '5000.00', '5000.00', '750.00', '0.00', 'COB HERITAGE • 1,600M MSL', 1, 2, 4, 'Naturally thermal-insulated cob clay dwelling sculpted from native red earth, river sand, and straw. Features private sit-out and orchard veranda.', 'Hand-Carved Wooden Queen Bed, Natural Clay Cooler, Slate Hearth Fireplace, Terracotta Veranda, Private Organic Herb Garden, Forest Spring Water', NULL, 'assets/uploads/room_20261002_160428_ad2aaa44.jpg', '[{\"url\":\"assets/images/mudhouse_exterior.png\",\"title\":\"Earthen Exterior & Veranda\",\"description\":\"Cob-built earth architecture with terracotta roofing set amidst wild forest greenery.\",\"order\":1},{\"url\":\"assets/images/mudhouse_interior.png\",\"title\":\"Arched Mud Interior & Living Suite\",\"description\":\"Curved earthen arches, handcrafted timber ceiling, and organic linen bedding.\",\"order\":2},{\"url\":\"assets/images/01 (7).jpeg\",\"title\":\"Clay Hearth & Veranda View\",\"description\":\"Naturally cooled thermal mud walls with private veranda overlooking plantation.\",\"order\":3},{\"url\":\"assets/images/01 (8).jpeg\",\"title\":\"Forest Canopy Window Alcove\",\"description\":\"Morning sunlight streaming through large openable high-altitude forest windows.\",\"order\":4},{\"url\":\"assets/images/01 (1).jpeg\",\"title\":\"Terracotta Veranda & Morning Mist\",\"description\":\"Private sitting porch surrounded by cardamom and pepper vines.\",\"order\":5},{\"url\":\"assets/images/01 (2).jpeg\",\"title\":\"Living Soil & Landscape Setting\",\"description\":\"Direct path leading from cottage porch to organic vegetable beds.\",\"order\":6}]', NULL, NULL, 'assets/uploads/pano_20261007_074443_f25c22d9.jpg', '{\"badge\":\"FOOD FOREST IMMERSIVE ARCHITECTURAL TOUR\",\"subtitle\":\"Scroll down to journey from the terraced flower garden into the hand-sculpted mudhouse suite.\",\"progressLabels\":[\"Garden Exterior\",\"Glass Façade\",\"Daybed Alcove\",\"Living Suite\",\"Clay Hearth\"],\"stages\":[{\"pill\":\"<i class=\\\"fa-solid fa-house-chimney\\\"></i> ORGANIC COB ARCHITECTURE\",\"heading\":\"Cob Exterior & Terraced Orchard Garden\",\"text\":\"Handcrafted from unbaked clay, straw, and river silt with terracotta tiled eaves, overlooking misty mountain apple orchards and organic flower gardens.\"},{\"pill\":\"<i class=\\\"fa-solid fa-mountain-sun\\\"></i> 01 • HIGH GLASS FAÇADE\",\"heading\":\"Floor-to-Ceiling Mountain Vista Glass\",\"text\":\"Dramatic cathedral-height glass portal framing panoramic views of Kanthalloor\'s cloud-swept peaks, rolling pine forests, and stone garden walkways.\"},{\"pill\":\"<i class=\\\"fa-solid fa-couch\\\"></i> 02 • TRADITIONAL DAYBED ALCOVE\",\"heading\":\"Sculpted Earthen Alcove & Teak Pillars\",\"text\":\"An organic sunlit daybed recessed into sculpted clay walls with antique carved teak columns, designed for afternoon reading and tranquil tea sessions.\"},{\"pill\":\"<i class=\\\"fa-solid fa-bed\\\"></i> 03 • HANDCRAFTED LIVING & SLEEP SUITE\",\"heading\":\"Artisan Wood Furniture & Terracotta Floors\",\"text\":\"Handmade terracotta floor tiles, antique wood coffee tables, woven carpets, and natural linen luxury bedding under soaring exposed timber roof trusses.\"},{\"pill\":\"<i class=\\\"fa-solid fa-fire\\\"></i> 04 • CLAY HEARTH & BRASS LANTERNS\",\"heading\":\"Artisan Stone Fireplace & Ambient Glow\",\"text\":\"Authentic hearth with hand-cut stone surround, brass lantern lighting, and curated botanical ceramics creating an enchanting evening sanctuary.\"}]}', 1, 'available', '2026-09-24 09:25:17'),
(16, 'canopy-treehouse', 'woodhouse', 'single_hut', 'Luxury Canopy Treehouse', '5000.00', '5000.00', '750.00', '0.00', '30FT ELEVATION • 1,620M MSL', 1, 2, 4, 'Suspended 30 feet above the forest floor within ancient trees. Crafted with wild teak timber, an open cantilevered deck, and expansive curved glass with panoramic mist views.', 'King Artisan Teak Bed, Mountain-View Cantilevered Deck, Solar-Heated Rain Shower, Handcrafted Herbal Teas, Ambient Fire Hearth, Telescope for Stargazing, Zero-Plastic Toiletries', NULL, 'assets/uploads/room_cover_20261008_195334_9730d04e.jpg', '[\"assets\\/images\\/treehouse_exterior_front.jpg\",\"assets\\/images\\/treehouse_interior.png\",\"assets\\/images\\/treehouse_exterior.png\",\"assets\\/images\\/01 (10).jpeg\",\"assets\\/images\\/treehouse_360_pano.jpg\"]', NULL, NULL, 'assets/uploads/pano_20261008_195502_9d2b43e9.jpg', '{\"badge\":\"FOOD FOREST IMMERSIVE ARCHITECTURAL TOUR\",\"subtitle\":\"Scroll down to fly from the misty forest canopy directly inside the 360° suite.\",\"progressLabels\":[\"Exterior\",\"Panoramic Bay\",\"Forest Deck\",\"Master Suite\",\"Stone Hearth\"],\"stages\":[{\"pill\":\"<i class=\\\"fa-solid fa-tree\\\"></i> 30FT ELEVATION • 1,620M MSL\",\"heading\":\"Front Exterior & Forest Suspension\",\"text\":\"Suspended 30 feet above the forest floor within ancient trees. Crafted with wild teak timber, an open cantilevered deck, and expansive curved glass.\"},{\"pill\":\"<i class=\\\"fa-solid fa-mountain-sun\\\"></i> 01 • 180° VALLEY GLASSWORK\",\"heading\":\"Floor-to-Ceiling Curved Bay Window\",\"text\":\"An expansive architectural curved window framing floating clouds, high-altitude tea valleys, and morning mountain mist.\"},{\"pill\":\"<i class=\\\"fa-solid fa-wind\\\"></i> 02 • MISTY CANOPY DECK\",\"heading\":\"Private Cantilevered Timber Balcony\",\"text\":\"Step directly outside into the clouds. An open timber deck perched 30 feet high in ancient trees for birdsong and organic mountain tea.\"},{\"pill\":\"<i class=\\\"fa-solid fa-bed\\\"></i> 03 • WILD TEAK BED SUITE\",\"heading\":\"Handcrafted Artisan King Bed\",\"text\":\"Hand-hewn from natural wild teak, dressed in 100% breathable organic linen, accompanied by handcrafted bedside lanterns and radial wooden ceiling beams.\"},{\"pill\":\"<i class=\\\"fa-solid fa-fire\\\"></i> 04 • THE FOREST HEARTH\",\"heading\":\"Hand-Cut Stone Fireplace & Lounge\",\"text\":\"Warm authentic stone fireplace with crackling hearth wood, curved luxury sofa, and library nook to relax on crisp mountain evenings.\"}]}', 1, 'available', '2026-09-30 14:35:24'),
(17, 'duplex-suite-01', 'woodhouse', 'duplex_hut', 'Duplex Chalet Suite 01', '8000.00', '4000.00', '750.00', '0.00', 'UPPER RIDGE • 1,600M MSL', 2, 4, 8, 'High-elevation sanctuary duplex suite with morning mist exposure, two independent master bedrooms, private panoramic balconies, and shared lounge.', '2 Master Bedrooms with Ensuite Baths, Dual Panoramic Balconies, Private Sun Lounge, Hearth Fireplace, Double Rain Showers, Farm Breakfast & Dinners Included', NULL, 'assets/images/duplex_suite_exterior.jpg', '[\"assets\\/images\\/duplex_suite_exterior.jpg\",\"assets\\/images\\/treehouse_interior.png\",\"assets\\/images\\/01 (2).jpeg\",\"assets\\/images\\/01 (10).jpeg\",\"assets\\/images\\/treehouse_exterior.png\"]', '[\"assets\\/images\\/treehouse_interior.png\",\"assets\\/images\\/01 (2).jpeg\",\"assets\\/images\\/01 (10).jpeg\"]', '[\"assets\\/images\\/treehouse_interior_pano.jpg\",\"assets\\/images\\/01 (25).jpeg\",\"assets\\/images\\/01 (32).jpeg\"]', 'assets/images/treehouse_360_pano.jpg', '{\"badge\":\"FOOD FOREST IMMERSIVE ARCHITECTURAL TOUR\",\"subtitle\":\"Scroll down to fly from the misty forest canopy directly inside the 360° suite.\",\"progressLabels\":[\"Exterior\",\"Panoramic Bay\",\"Forest Deck\",\"Master Suite\",\"Stone Hearth\"],\"stages\":[{\"pill\":\"<i class=\\\"fa-solid fa-tree\\\"></i> UPPER RIDGE • 1,600M MSL\",\"heading\":\"Front Exterior & Forest Suspension\",\"text\":\"Suspended 30 feet above the forest floor within ancient trees. Crafted with wild teak timber, an open cantilevered deck, and expansive curved glass.\"},{\"pill\":\"<i class=\\\"fa-solid fa-mountain-sun\\\"></i> 01 • 180° VALLEY GLASSWORK\",\"heading\":\"Floor-to-Ceiling Curved Bay Window\",\"text\":\"An expansive architectural curved window framing floating clouds, high-altitude tea valleys, and morning mountain mist.\"},{\"pill\":\"<i class=\\\"fa-solid fa-wind\\\"></i> 02 • MISTY CANOPY DECK\",\"heading\":\"Private Cantilevered Timber Balcony\",\"text\":\"Step directly outside into the clouds. An open timber deck perched 30 feet high in ancient trees for birdsong and organic mountain tea.\"},{\"pill\":\"<i class=\\\"fa-solid fa-bed\\\"></i> 03 • WILD TEAK BED SUITE\",\"heading\":\"Handcrafted Artisan King Bed\",\"text\":\"Hand-hewn from natural wild teak, dressed in 100% breathable organic linen, accompanied by handcrafted bedside lanterns and radial wooden ceiling beams.\"},{\"pill\":\"<i class=\\\"fa-solid fa-fire\\\"></i> 04 • THE FOREST HEARTH\",\"heading\":\"Hand-Cut Stone Fireplace & Lounge\",\"text\":\"Warm authentic stone fireplace with crackling hearth wood, curved luxury sofa, and library nook to relax on crisp mountain evenings.\"}]}', 1, 'available', '2026-09-30 14:35:24'),
(18, 'duplex-suite-02', 'woodhouse', 'duplex_hut', 'Duplex Chalet Suite 02', '8000.00', '4000.00', '750.00', '0.00', 'UPPER RIDGE • 1,600M MSL', 2, 4, 8, 'Two-tier alpine timber duplex overlooking rolling mountain cloudscapes with dual handcrafted king beds and private verandas.', '2 Master Bedrooms with Ensuite Baths, Dual Panoramic Balconies, Private Sun Lounge, Hearth Fireplace, Double Rain Showers, Farm Breakfast & Dinners Included', NULL, 'assets/images/duplex_suite_exterior.jpg', '[\"assets\\/images\\/duplex_suite_exterior.jpg\",\"assets\\/images\\/treehouse_interior.png\",\"assets\\/images\\/01 (2).jpeg\",\"assets\\/images\\/01 (25).jpeg\",\"assets\\/images\\/01 (32).jpeg\"]', '[\"assets\\/images\\/treehouse_interior.png\",\"assets\\/images\\/01 (2).jpeg\",\"assets\\/images\\/01 (25).jpeg\"]', '[\"assets\\/images\\/treehouse_interior_pano.jpg\",\"assets\\/images\\/01 (32).jpeg\",\"assets\\/images\\/01 (26).jpeg\"]', 'assets/images/treehouse_360_pano.jpg', '{\"badge\":\"FOOD FOREST IMMERSIVE ARCHITECTURAL TOUR\",\"subtitle\":\"Scroll down to fly from the misty forest canopy directly inside the 360° suite.\",\"progressLabels\":[\"Exterior\",\"Panoramic Bay\",\"Forest Deck\",\"Master Suite\",\"Stone Hearth\"],\"stages\":[{\"pill\":\"<i class=\\\"fa-solid fa-tree\\\"></i> UPPER RIDGE • 1,600M MSL\",\"heading\":\"Front Exterior & Forest Suspension\",\"text\":\"Suspended 30 feet above the forest floor within ancient trees. Crafted with wild teak timber, an open cantilevered deck, and expansive curved glass.\"},{\"pill\":\"<i class=\\\"fa-solid fa-mountain-sun\\\"></i> 01 • 180° VALLEY GLASSWORK\",\"heading\":\"Floor-to-Ceiling Curved Bay Window\",\"text\":\"An expansive architectural curved window framing floating clouds, high-altitude tea valleys, and morning mountain mist.\"},{\"pill\":\"<i class=\\\"fa-solid fa-wind\\\"></i> 02 • MISTY CANOPY DECK\",\"heading\":\"Private Cantilevered Timber Balcony\",\"text\":\"Step directly outside into the clouds. An open timber deck perched 30 feet high in ancient trees for birdsong and organic mountain tea.\"},{\"pill\":\"<i class=\\\"fa-solid fa-bed\\\"></i> 03 • WILD TEAK BED SUITE\",\"heading\":\"Handcrafted Artisan King Bed\",\"text\":\"Hand-hewn from natural wild teak, dressed in 100% breathable organic linen, accompanied by handcrafted bedside lanterns and radial wooden ceiling beams.\"},{\"pill\":\"<i class=\\\"fa-solid fa-fire\\\"></i> 04 • THE FOREST HEARTH\",\"heading\":\"Hand-Cut Stone Fireplace & Lounge\",\"text\":\"Warm authentic stone fireplace with crackling hearth wood, curved luxury sofa, and library nook to relax on crisp mountain evenings.\"}]}', 1, 'available', '2026-09-30 14:35:24'),
