('room_audit_checklist', '[{\"item\":\"Physical Room Key & Brass Keychain\",\"qty\":1,\"notes\":\"Handover at reception\"},{\"item\":\"TV Unit & Set-Top Box\",\"qty\":1,\"notes\":\"Screen undamaged, cables intact\"},{\"item\":\"TV Remote & Set-Top Remote\",\"qty\":2,\"notes\":\"Both remotes working with batteries\"},{\"item\":\"Electric Water Kettle & Ceramic Tray\",\"qty\":1,\"notes\":\"Clean & working condition\"},{\"item\":\"Artisan Coffee Mugs & Spoons\",\"qty\":2,\"notes\":\"Earthen/ceramic sets intact\"},{\"item\":\"Glass Water Pitcher / Spring Bottles\",\"qty\":2,\"notes\":\"Sanitized glass carafes\"},{\"item\":\"Hairdryer (Grooming Kit)\",\"qty\":1,\"notes\":\"Kept in bathroom drawer\"},{\"item\":\"Emergency High-Beam LED Torch\",\"qty\":1,\"notes\":\"Rechargeable forest torch\"},{\"item\":\"Heavy-Duty Walking Umbrellas\",\"qty\":2,\"notes\":\"In umbrella stand at entrance\"},{\"item\":\"Mosquito Vaporizer Unit\",\"qty\":1,\"notes\":\"Plugged in bedside socket\"},{\"item\":\"Organic Cotton Bath & Hand Towels\",\"qty\":4,\"notes\":\"2 Large Bath + 2 Hand Towels\"},{\"item\":\"Heavy Duck-Down Quilts & Blankets\",\"qty\":2,\"notes\":\"In wardrobe / master bed\"},{\"item\":\"Balcony Cane Chairs & Teak Table\",\"qty\":1,\"notes\":\"Sit-out furniture undamaged\"},{\"item\":\"Fireplace Guard / Tool Set\",\"qty\":1,\"notes\":\"If hearth villa\"}]'),
